static TreeMap<Long, String> events = new TreeMap<>();
static {
    events.put(1000L, "Start"); events.put(2000L, "Login"); events.put(5000L, "Zakup"); events.put(8000L, "Wylogowanie");
}

static Map.Entry<Long, String> getEventNear(long timestamp) {
    Map.Entry<Long, String> floor = events.floorEntry(timestamp);
    Map.Entry<Long, String> ceiling = events.ceilingEntry(timestamp);
    if (floor == null) return ceiling;
    if (ceiling == null) return floor;
    return (timestamp - floor.getKey() <= ceiling.getKey() - timestamp) ? floor : ceiling;
}

public static void main(String[] args) {
    System.out.println(getEventNear(3500));
}

