int[] nums = {1, 3, -1, -3, 5, 3, 6, 7};
int k = 3;
List<Double> medians = new ArrayList<>();

for (int i = 0; i <= nums.length - k; i++) {
    TreeMap<Integer, Integer> window = new TreeMap<>();
    for (int j = i; j < i + k; j++) {
        window.merge(nums[j], 1, Integer::sum);
    }
    int targetIndex = k / 2;
    int count = 0;
    int median = 0;
    for (Map.Entry<Integer, Integer> entry : window.entrySet()) {
        count += entry.getValue();
        if (count > targetIndex) { median = entry.getKey(); break; }
    }
    medians.add((double) median);
}
System.out.println("Mediany okien: " + medians);

