Map<Integer, Map<Integer, Integer>> graph = Map.of(
    1, Map.of(2, 4, 3, 1),
    2, Map.of(4, 1),
    3, Map.of(2, 1, 4, 5),
    4, Map.of()
);
int source = 1;
Map<Integer, Integer> dist = new HashMap<>();
for (int node : graph.keySet()) dist.put(node, Integer.MAX_VALUE);
dist.put(source, 0);

TreeMap<Integer, Integer> pq = new TreeMap<>();
pq.put(0, source);

while (!pq.isEmpty()) {
    Map.Entry<Integer, Integer> entry = pq.pollFirstEntry();
    int d = entry.getKey(), node = entry.getValue();
    if (d > dist.get(node)) continue;
    for (Map.Entry<Integer, Integer> edge : graph.getOrDefault(node, Map.of()).entrySet()) {
        int newDist = d + edge.getValue();
        if (newDist < dist.get(edge.getKey())) {
            dist.put(edge.getKey(), newDist);
            pq.put(newDist, edge.getKey()); // UWAGA: moze nadpisac wpis o tej samej odleglosci!
        }
    }
}
System.out.println("Odleglosci: " + dist);

