static TreeMap<Integer, Integer> sprzedazDzienna = new TreeMap<>();
static {
    for (int day = 1; day <= 30; day++) sprzedazDzienna.put(day, day * 100);
}

static int sumInRange(int from, int to) {
    return sprzedazDzienna.subMap(from, true, to, true).values().stream()
            .mapToInt(Integer::intValue).sum();
}

public static void main(String[] args) {
    System.out.println("Suma dni 10-15: " + sumInRange(10, 15));
}

class TaskScheduler {
    private final TreeMap<Integer, List<String>> tasks = new TreeMap<>();

    void addTask(int priority, String task) {
        tasks.computeIfAbsent(priority, k -> new ArrayList<>()).add(task);
    }

    String pollNextTask() {
        if (tasks.isEmpty()) return null;
        int topPriority = tasks.firstKey();
        List<String> list = tasks.get(topPriority);
        String task = list.remove(0);
        if (list.isEmpty()) {
            tasks.remove(topPriority);
        }
        return task;
    }
}

TaskScheduler scheduler = new TaskScheduler();
scheduler.addTask(2, "Napisz raport");
scheduler.addTask(1, "Napraw krytyczny bug");
scheduler.addTask(1, "Deploy na prod");
scheduler.addTask(3, "Dokumentacja");

System.out.println(scheduler.pollNextTask()); // Napraw krytyczny bug
System.out.println(scheduler.pollNextTask()); // Deploy na prod
System.out.println(scheduler.pollNextTask()); // Napisz raport
